import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

gelu_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void gelu_kernel_vec4(const float4* __restrict__ x, float4* __restrict__ y, int n4) {
    const float c = 0.7978845608028654f; // sqrt(2/pi)
    const float ca = c * 0.044715f;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    #pragma unroll 4
    for (; idx < n4; idx += stride) {
        float4 in = __ldg(&x[idx]);
        float4 out;
        float x0 = in.x, x1 = in.y, x2 = in.z, x3 = in.w;
        float sq0 = x0 * x0, sq1 = x1 * x1, sq2 = x2 * x2, sq3 = x3 * x3;
        float t0 = fmaf(ca * sq0, x0, c * x0);
        float t1 = fmaf(ca * sq1, x1, c * x1);
        float t2 = fmaf(ca * sq2, x2, c * x2);
        float t3 = fmaf(ca * sq3, x3, c * x3);
        out.x = 0.5f * x0 * (1.0f + tanhf(t0));
        out.y = 0.5f * x1 * (1.0f + tanhf(t1));
        out.z = 0.5f * x2 * (1.0f + tanhf(t2));
        out.w = 0.5f * x3 * (1.0f + tanhf(t3));
        y[idx] = out;
    }
}
__global__ void gelu_kernel_scalar(const float* __restrict__ x, float* __restrict__ y, int n) {
    const float c = 0.7978845608028654f;
    const float a = 0.044715f;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    for (; idx < n; idx += stride) {
        float xv = x[idx];
        float t = c * (xv + a * xv * xv * xv);
        y[idx] = 0.5f * xv * (1.0f + tanhf(t));
    }
}
torch::Tensor gelu_cuda(torch::Tensor x) {
    auto y = torch::empty_like(x);
    int n = x.numel();
    int n4 = n / 4;
    int remainder = n - n4 * 4;
    if (n4 > 0) {
        int min_grid_size = 0;
        int block_size = 0;
        cudaOccupancyMaxPotentialBlockSize(&min_grid_size, &block_size,
                                            gelu_kernel_vec4, 0, 0);
        int blocks = (n4 + block_size - 1) / block_size;
        if (blocks < min_grid_size) blocks = min_grid_size;
        gelu_kernel_vec4<<<blocks, block_size>>>(
            reinterpret_cast<const float4*>(x.data_ptr<float>()),
            reinterpret_cast<float4*>(y.data_ptr<float>()),
            n4
        );
    }
    if (remainder > 0) {
        int tail_offset = n4 * 4;
        int min_grid_size = 0;
        int block_size = 0;
        cudaOccupancyMaxPotentialBlockSize(&min_grid_size, &block_size,
                                            gelu_kernel_scalar, 0, 0);
        int blocks = (remainder + block_size - 1) / block_size;
        if (blocks < 1) blocks = 1;
        gelu_kernel_scalar<<<blocks, block_size>>>(
            x.data_ptr<float>() + tail_offset,
            y.data_ptr<float>() + tail_offset,
            remainder
        );
    }
    return y;
}
"""

gelu_cpp_source = "torch::Tensor gelu_cuda(torch::Tensor x);"

gelu_module = load_inline(
    name="gelu_module",
    cpp_sources=gelu_cpp_source,
    cuda_sources=gelu_source,
    functions=["gelu_cuda"],
    extra_cuda_cflags=["--use_fast_math"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.gelu = gelu_module

    def forward(self, x):
        return self.gelu.gelu_cuda(x.cuda().contiguous())


def get_inputs():
    return [torch.rand(8192, 8192)]


def get_init_inputs():
